def max_dominating_set_size(n):
    # For the set {1, ..., n}, the maximum size of a dominating set
    # that ensures all non-P elements are neighbors of P is ceiling(n/2).
    # This is achieved by P = {1, 3, 5, ...}
    return (n + 1) // 2

print("N | Max |P|")
for n in range(1, 21):
    print(f"{n} | {max_dominating_set_size(n)}")

